<?php
require_once __DIR__ . '/../config/database.php';
$id=(int)($_GET['id']??0);
if($id<=0){http_response_code(400);exit('ID tidak valid.');}
try{$pdo=(new Database())->connect();$st=$pdo->prepare("SELECT i.*,c.name,c.phone,c.address,c.pppoe_username,c.package_name FROM billing_invoices i JOIN billing_customers c ON c.id=i.customer_id WHERE i.id=? AND i.status='paid'");$st->execute([$id]);$r=$st->fetch(PDO::FETCH_ASSOC);if(!$r){http_response_code(404);exit('Pembayaran tidak ditemukan.');}}catch(Throwable $e){http_response_code(500);exit('Gagal mengambil data.');}
function h($v){return htmlspecialchars((string)($v??'-'),ENT_QUOTES,'UTF-8');}
function rupiah($v){return 'Rp '.number_format((float)$v,0,',','.');}
?>
