<div class="receipt"><div class="top"><div><div class="brand">NetMonitor</div><div class="muted">Billing PPPoE</div></div><div class="title">KWITANSI<br><span class="muted"><?=h($r['invoice_no'])?></span></div></div>
<div class="grid"><div><div class="label">Diterima dari</div><div class="value"><?=h($r['name'])?></div><div class="muted"><?=h($r['phone'])?></div></div><div><div class="label">Username PPPoE</div><div class="value"><?=h($r['pppoe_username'])?></div><div class="muted">Paket <?=h($r['package_name'])?></div></div><div><div class="label">Periode</div><div class="value"><?=h($r['period'])?></div></div><div><div class="label">Tanggal pembayaran</div><div class="value"><?=h($r['paid_at'])?></div></div></div>
